  addPerson(kit, 0.5, h.deck(L * 0.38), L * 0.38, 0, seed + 5);
  g.add(kit.build('navy-training-boat-hull'));
  navLights(g, { length: L, beam, mastY: cy + 4.6, mastZ: cz - cl * 0.22, sideY: cy + 1.8 });
  return g;
